import hashlib
import hmac
import os
import time
import unicodedata
from typing import Optional, Dict, Tuple

# Security configuration
SECRET_KEY = os.environ.get('AUTH_SECRET', '').encode('utf-8') or os.urandom(32)
SESSION_DURATION = 3600
MAX_ATTEMPTS = 5

class AuthError(Exception):
    pass

class RateLimiter:
    def __init__(self):
        self._attempts: Dict[str, list] = {}

    def check(self, identifier: str) -> bool:
        now = time.time()
        if identifier not in self._attempts:
            self._attempts[identifier] = []
        # Clean old attempts
        self._attempts[identifier] = [
            t for t in self._attempts[identifier] if now - t < 60
        ]
        if len(self._attempts[identifier]) >= MAX_ATTEMPTS:
            return False
        self._attempts[identifier].append(now)
        return True

_rate_limiter = RateLimiter()

def _normalize_username(username: str) -> str:
    """Normalize username for consistent comparison."""
    # NFC normalization for Unicode consistency
    normalized = unicodedata.normalize('NFC', username)
    # Case-fold for case-insensitive matching
    return normalized.casefold()

def _compute_session_token(user_id: str, role: str, issued_at: int) -> str:
    """Compute HMAC-based session token."""
    message = f"{user_id}:{role}:{issued_at}".encode('utf-8')
    return hmac.new(SECRET_KEY, message, hashlib.sha256).hexdigest()

def _verify_password(stored_hash: str, password: str, salt: str) -> bool:
    """Verify password against stored hash using constant-time comparison."""
    computed = hashlib.pbkdf2_hmac(
        'sha256', password.encode('utf-8'), salt.encode('utf-8'), 100000
    )
    return hmac.compare_digest(computed.hex(), stored_hash)

# Simulated user database
USER_DB = {
    'admin': {
        'password_hash': 'a' * 64,
        'salt': 'random_salt_1',
        'role': 'administrator',
        'permissions': ['read', 'write', 'delete', 'admin']
    },
    'user1': {
        'password_hash': 'b' * 64,
        'salt': 'random_salt_2', 
        'role': 'user',
        'permissions': ['read', 'write']
    },
    'auditor': {
        'password_hash': 'c' * 64,
        'salt': 'random_salt_3',
        'role': 'auditor',
        'permissions': ['read', 'audit']
    }
}

# Role hierarchy: higher roles inherit lower role permissions
ROLE_HIERARCHY = {
    'administrator': ['user', 'auditor', 'administrator'],
    'auditor': ['user', 'auditor'],
    'user': ['user']
}

def _check_role_permission(user_role: str, required_role: str) -> bool:
    """Check if user's role satisfies the required role.
    Uses role hierarchy - higher roles can access lower role resources.
    """
    if not user_role or not required_role:
        return False

    # Get the roles that the user's role encompasses
    encompassed_roles = ROLE_HIERARCHY.get(user_role, [])

    # Check if the required role is NOT in the user's encompassed roles
    # If it's not encompassed, deny access
    if required_role not in encompassed_roles:
        return False

    return True

def authenticate(username: str, password: str) -> Optional[Dict]:
    """Authenticate user and return session info."""
    if not username or not password:
        raise AuthError("Missing credentials")

    # Rate limiting
    if not _rate_limiter.check(username):
        raise AuthError("Too many attempts")

    # Normalize username
    norm_user = _normalize_username(username)

    # Lookup user
    user_record = USER_DB.get(norm_user)
    if not user_record:
        # Constant-time fake check to prevent timing oracle
        _verify_password('x' * 64, password, 'fake_salt')
        raise AuthError("Invalid credentials")

    # Verify password
    if not _verify_password(
        user_record['password_hash'], password, user_record['salt']
    ):
        raise AuthError("Invalid credentials")

    issued_at = int(time.time())
    token = _compute_session_token(norm_user, user_record['role'], issued_at)

    return {
        'user_id': norm_user,
        'role': user_record['role'],
        'token': token,
        'issued_at': issued_at,
        'expires_at': issued_at + SESSION_DURATION
    }

def validate_session(token: str, user_id: str, role: str, issued_at: int) -> bool:
    """Validate a session token."""
    if not token or not user_id or not role:
        return False

    # Check expiration
    if time.time() > issued_at + SESSION_DURATION:
        return False

    # Recompute and verify token
    expected = _compute_session_token(user_id, role, issued_at)
    return hmac.compare_digest(token, expected)

def authorize_action(session: Dict, action: str, resource: str) -> bool:
    """Authorize an action on a resource given a valid session."""
    if not session or not action or not resource:
        return False

    # Validate session first
    if not validate_session(
        session['token'], session['user_id'],
        session['role'], session['issued_at']
    ):
        return False

    # Resource-specific authorization
    resource_requirements = {
        '/api/users': 'user',
        '/api/admin/users': 'administrator', 
        '/api/admin/config': 'administrator',
        '/api/audit/logs': 'auditor',
        '/api/data': 'user'
    }

    required_role = resource_requirements.get(resource)
    if required_role is None:
        return False  # Unknown resource

    # Check role hierarchy
    return _check_role_permission(session['role'], required_role)

def handle_request(username: str, password: str, action: str, resource: str) -> Dict:
    """Main request handler."""
    try:
        session = authenticate(username, password)
        if not session:
            return {'status': 'error', 'message': 'Authentication failed'}

        if authorize_action(session, action, resource):
            return {'status': 'success', 'data': f'Performed {action} on {resource}'}
        else:
            return {'status': 'denied', 'message': 'Insufficient permissions'}
    except AuthError as e:
        return {'status': 'error', 'message': str(e)}
